import Foundation
import XCTest
@testable import ApexKit

/// Replays Tests/Fixtures/live_fixture.json (generated by tools/make_live_fixture.py from
/// core/live_pipeline.py) and requires ApexKit to reproduce every recorded value.
final class LiveFixtureTests: XCTestCase {
    static let fixture: [String: Any] = {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .deletingLastPathComponent().appendingPathComponent("Fixtures/live_fixture.json")
        let data = try! Data(contentsOf: url)
        return try! JSONSerialization.jsonObject(with: data) as! [String: Any]
    }()

    func doubles(_ key: String) -> [Double] { (Self.fixture[key] as! [Any]).map { ($0 as! NSNumber).doubleValue } }
    func rows(_ key: String) -> [[Double]] { (Self.fixture[key] as! [[Any]]).map { $0.map { ($0 as! NSNumber).doubleValue } } }
    /// Rows where JSON null (unknown, e.g. camber off a corner) reads as nil.
    func optionalRows(_ key: String) -> [[Double?]] { (Self.fixture[key] as! [[Any]]).map { $0.map { ($0 as? NSNumber)?.doubleValue } } }

    func runPipeline(_ check: (Int, IMUPipeline) -> Void) {
        let t = doubles("t"), speed = doubles("speed")
        let accel = rows("accel"), gyro = rows("gyro"), gravity = rows("gravity")
        var pipe = IMUPipeline()
        for i in 0..<t.count {
            pipe.step(accel: Vec3(accel[i]), gyro: Vec3(gyro[i]), timestamp: t[i], speedMps: speed[i], gravityG: Vec3(gravity[i]))
            check(i, pipe)
            if i % 50 == 0 { _ = pipe.takeVertPeak() }   // same windows as tools/make_live_fixture.py
        }
    }

    func testIMUPipelineMatchesReference() {
        var expected: [Int: [Double?]] = [:]
        for row in optionalRows("outputs_every_10") { expected[Int(row[0]!)] = Array(row.dropFirst()) }
        var compared = 0
        runPipeline { i, pipe in
            guard let want = expected[i] else { return }
            for (k, (got, exp)) in zip(pipe.outputs, want).enumerated() {
                guard let exp else { XCTAssertNil(got, "sample \(i) output \(k): unknown stays unknown"); continue }
                guard let got else { XCTFail("sample \(i) output \(k): nil, want \(exp)"); continue }
                XCTAssertEqual(got, exp, accuracy: 1e-9 * max(1.0, abs(exp)), "sample \(i) output \(k)")
            }
            compared += 1
        }
        XCTAssertEqual(compared, expected.count)
    }

    func testMountCalibrationMatchesReferenceAndRecoversTheMount() {
        var states: [Int: (String, [Double])] = [:]
        for row in Self.fixture["mount_every_10"] as! [[Any]] {
            let idx = (row[0] as! NSNumber).intValue
            states[idx] = (row[1] as! String, row.dropFirst(2).map { ($0 as! NSNumber).doubleValue })
        }
        var final = MountCalibrator(), beforeRemount = MountCalibrator()
        runPipeline { i, pipe in
            if let (state, rows) = states[i] {
                XCTAssertEqual(pipe.mount.state.rawValue, state, "sample \(i)")
                for (a, b) in zip(pipe.mount.rows, rows) { XCTAssertEqual(a, b, accuracy: 1e-9) }
            }
            if i == 3000 { beforeRemount = pipe.mount }
            final = pipe.mount
        }
        // Physics, not just parity: solved by itself (no tap), before and after the remount, rows = true rotation transposed.
        for (mount, key) in [(beforeRemount, "true_veh_to_phone"), (final, "true_veh_to_phone_after_remount")] {
            let truth = rows(key)
            XCTAssertEqual(mount.state, .locked, key)
            for r in 0..<3 { for c in 0..<3 { XCTAssertEqual(mount.rows[r * 3 + c], truth[c][r], accuracy: 1e-3, key) } }
        }
    }

    func testCamberReadsTheBankInTheTurn() {
        var samples: [Double] = []
        runPipeline { i, pipe in if (1800..<2550).contains(i), let c = pipe.camberRad { samples.append(c) } }
        XCTAssertEqual(samples.count, 750, "measured all through the turn")
        let meanDeg = samples.reduce(0, +) / Double(samples.count) * 180 / .pi
        XCTAssertEqual(meanDeg, 4.0, accuracy: 0.3)   // fixture banks the turn at 4 degrees
    }

    func testCamberIsUnknownOnAStraightNeverZero() {
        // before the first turn (pulling away, braking) and on the straight after it (26 s), past the hold: nil, not 0
        var straight = 0, known = 0
        runPipeline { i, pipe in
            if (500..<1500).contains(i) || (2800..<3100).contains(i) {
                straight += 1
                if pipe.camberRad != nil { known += 1 }
            }
        }
        XCTAssertEqual(straight, 1300)
        XCTAssertEqual(known, 0)
        // a corner holds its value for camberHoldS after its last cornering sample, then it is unknown
        var pipe = IMUPipeline()
        pipe.mount = MountCalibrator(rows: [1, 0, 0, 0, 1, 0, 0, 0, 1])
        for i in 0..<300 {
            pipe.step(accel: Vec3(x: 0, y: 4.0, z: 0), gyro: Vec3(x: 0, y: 0, z: 0.2), timestamp: Double(i) * 0.01, speedMps: 20)
        }
        XCTAssertNotNil(pipe.camberRad)
        for i in 300..<500 {
            pipe.step(accel: Vec3(x: 0, y: 0, z: 0), gyro: Vec3(x: 0, y: 0, z: 0), timestamp: Double(i) * 0.01, speedMps: 20)
            if i == 350 { XCTAssertNotNil(pipe.camberRad, "held just after the corner") }
        }
        XCTAssertNil(pipe.camberRad)
    }

    func testOdometerAndElevationFusionMatchReference() {
        let gps = rows("gps")
        let expected = Self.fixture["nodes_per_fix"] as! [[[Any]]]
        let vAcc = (Self.fixture["gps_vertical_accuracy_m"] as! NSNumber).doubleValue
        let hAcc = (Self.fixture["gps_horizontal_accuracy_m"] as! NSNumber).doubleValue
        let rough = (Self.fixture["rough_rms_for_odometer"] as! NSNumber).doubleValue
        var fusion = ElevationFusion()
        var odo = Odometer5m()
        var total = 0
        for (k, fix) in gps.enumerated() {
            fusion.relativeBaroM = fix[4]
            fusion.ingestGPS(altitudeM: fix[3], verticalAccuracyM: vAcc)
            let nodes = odo.feed(lat: fix[1], lon: fix[2], elevationM: fusion.elevationM, speedMps: fix[5],
                                 horizontalAccuracyM: hAcc, roughRMSMps2: rough)
            XCTAssertEqual(nodes.count, expected[k].count, "fix \(k)")
            for (n, want) in zip(nodes, expected[k]) {
                XCTAssertEqual(n.lat, (want[0] as! NSNumber).doubleValue, accuracy: 1e-12)
                XCTAssertEqual(n.lon, (want[1] as! NSNumber).doubleValue, accuracy: 1e-12)
                XCTAssertEqual(n.elevationM!, (want[2] as! NSNumber).doubleValue, accuracy: 1e-9)
                XCTAssertEqual(n.gradePct, (want[3] as! NSNumber).doubleValue, accuracy: 1e-9)
            }
            total += nodes.count
        }
        XCTAssertGreaterThan(total, 80)
    }

    func testSignConventionsAreISO8855() {
        // Left turn in an unrotated mount: +Y lateral, +Z yaw.
        var pipe = IMUPipeline()
        pipe.mount = MountCalibrator(rows: [1, 0, 0, 0, 1, 0, 0, 0, 1])
        for i in 0..<300 {
            pipe.step(accel: Vec3(x: 0, y: 4.0, z: 0), gyro: Vec3(x: 0, y: 0, z: 0.2), timestamp: Double(i) * 0.01, speedMps: 20)
        }
        XCTAssertGreaterThan(pipe.latAccMps2, 3.9)
        XCTAssertGreaterThan(pipe.yawRateRadS, 0.19)
    }
}
